'use strict';
const $=id=>document.getElementById(id),N=x=>Number(x).toLocaleString('pt-BR',{maximumFractionDigits:0}),P=x=>(100*x).toLocaleString('pt-BR',{maximumFractionDigits:1})+'%',M=x=>Number(x).toLocaleString('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}),E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),F=s=>{let[a,y]=String(s).replaceAll('.','').split('/');a=a.padStart(6,'0');return a.slice(0,3)+'.'+a.slice(3)+'/'+y};
const names={global:'Frequência global',uf:'Referência por estado',linear_trajetoria:'Regressão logística · histórico',hgb_basico:'Boosting · atributos básicos',hgb_trajetoria:'Boosting · histórico',extra_trajetoria:'Extra Trees · histórico'};
const stages={alvara_pesquisa:'Alvará de pesquisa',inicio_pesquisa_comunicado:'Início de pesquisa comunicado',relatorio_final_positivo_protocolado:'Relatório positivo protocolado',relatorio_pesquisa_aprovado:'Relatório de pesquisa aprovado',requerimento_lavra:'Requerimento de lavra / complemento',concessao_lavra_publicada:'Concessão de lavra publicada',guia_utilizacao_autorizada:'Guia de utilização autorizada'};
let model,summary,predictions,journeys,active='overview',page=0,sortKey='score',sortDir=-1,currentRows=[];
async function get(url){const r=await fetch(url);if(!r.ok)throw Error('Não foi possível carregar os dados. Tente recarregar a página.');return r.json()}
function table(h,rows){return '<table><thead><tr>'+h.map(x=>'<th>'+E(x)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(x=>'<td>'+E(x)+'</td>').join('')+'</tr>').join('')+'</tbody></table>'}
function bars(items){const max=Math.max(...items.map(r=>r[1]),.001);return items.map(([label,v,txt,color])=>`<div><div class="bar-top"><span>${E(label)}</span><b>${E(txt)}</b></div><div class="track"><div class="fill ${color||''}" style="width:${Math.max(0,v/max*100)}%"></div></div></div>`).join('')}
function navigate(id){active=id;document.querySelectorAll('.view').forEach(x=>x.hidden=x.id!==id);document.querySelectorAll('[data-view]').forEach(x=>x.setAttribute('aria-current',x.dataset.view===id?'page':'false'));if(id==='simulation')loadPred();if(id==='journey')renderJourney();history.replaceState(null,'','#'+id)}
function renderOverview(){const g=$('group').value,rd=$('round').value;const sums=summary.overview.filter(x=>(!rd||String(x.round)===rd)&&(g==='todas'||x[g]));const count=k=>sums.reduce((a,r)=>a+(r[k]||0),0);$('kpis').innerHTML=[['Lances vencedores',M(count('bids')),'Valores nominais; não comprovam pagamento'],['Áreas ofertadas',N(count('n')),'Rodadas comerciais 1–5 e 8'],['Arrematações',N(count('won')),'Ocorrências por área e rodada'],['Áreas livres',N(count('free')),'Resultado ao final da rodada']].map(r=>`<article class="kpi"><span>${r[0]}</span><strong>${r[1]}</strong><small>${r[2]}</small></article>`).join('');$('outcomes').innerHTML=bars([['Arrematada',count('won'),N(count('won')),''],['Conquistada',count('claimed'),N(count('claimed')),'green'],['Livre',count('free'),N(count('free')),'gold']]);let rounds=[1,2,3,4,5,8].filter(r=>!rd||String(r)===rd),vals=rounds.map(r=>sums.filter(x=>x.round===r).reduce((a,x)=>a+x.bids,0)),max=Math.max(...vals,1);$('roundchart').innerHTML='<svg viewBox="0 0 600 220" role="img" aria-label="Lances vencedores por rodada">'+rounds.map((r,i)=>{let x=35+i*560/rounds.length,w=360/rounds.length,h=140*vals[i]/max;return `<rect x="${x}" y="${170-h}" width="${w}" height="${h}" rx="4" fill="#1351b4"><title>${r}ª rodada: ${M(vals[i])}</title></rect><text x="${x}" y="195">${r}ª</text><text x="${x}" y="${160-h}">${(vals[i]/1e6).toFixed(1)} mi</text>`}).join('')+'</svg>';const d=model.test.models[model.chosen];$('model-highlight').textContent=names[model.chosen];$('model-f1').textContent=d.f1_macro.toFixed(3).replace('.',',');$('model-summary').textContent='F1 macro na 8ª rodada: peso igual para arrematada, conquistada e livre. '+N(model.test.test_n)+' áreas avaliadas.';$('scope').textContent=g==='todas'?'Todas as substâncias cadastradas.':'Classificação retrospectiva SGM/MME 2/2021. Não equivale a uma lista atual de minerais críticos.'}
function renderModels(){const d=model.test.models[model.chosen],ref=model.test.models.uf;const ci=model.paired_bootstrap_vs_uf_ci95;$('model-verdict').textContent=`Escolha pelas rodadas 4 e 5: ${names[model.chosen]}. Na rodada 8, F1 macro de ${P(d.f1_macro)}, frente a ${P(ref.f1_macro)} da referência por estado. Intervalo de 95% para a diferença: ${(ci[0]*100).toFixed(1)} a ${(ci[1]*100).toFixed(1)} pontos percentuais. ${ci[0]>0?'Vantagem observada nesta avaliação retrospectiva; ainda requer validação em nova rodada.':'Não há vantagem consistente demonstrada frente à referência por estado.'}`;$('comparison').innerHTML=table(['Método','F1 macro','Acurácia balanceada','Log-loss ↓','Brier ↓'],Object.entries(model.test.models).map(([k,v])=>[names[k]+(k===model.chosen?' · selecionado':''),P(v.f1_macro),P(v.balanced_accuracy),v.log_loss.toFixed(3),v.brier_multiclass.toFixed(3)]));$('confusion').innerHTML=table(['Observado → previsto',...model.labels],d.confusion.map((r,i)=>[model.labels[i],...r.map(N)]));$('importance').innerHTML=bars(model.permutation_importance.map(r=>[r.family,Math.max(0,r.mean_f1_drop),(r.mean_f1_drop*100).toFixed(1)+' p.p.','']));$('validations').innerHTML=table(['Rodada','Treino','Método','F1 macro'],Object.entries(model.validation).flatMap(([rd,d])=>Object.entries(d.models).map(([k,v])=>[rd,N(d.train_n),names[k],P(v.f1_macro)])));$('subgroups').innerHTML=table(['Recorte da 8ª rodada','Áreas','F1 modelo','F1 referência UF'],Object.entries(model.subgroups).map(([g,d])=>[g==='estrategico'?'Estratégicos (2021)':'Alta tecnologia (2021)',N(d.selected?.n||0),P(d.selected?.f1_macro||0),P(d.uf?.f1_macro||0)]));$('feature-list').textContent=model.chosen.includes('basico')?'UF, regime, logaritmo da área em hectares e ano do processo.':'UF, regime, área e ano do processo; eventos anteriores ao corte, duração e frequência do histórico, documentos, títulos e associações. Nenhum resultado ou CFEM posterior é atributo.'}
async function loadPred(){if(!predictions){try{predictions=await get('pesquisa/predicoes_v5.json');$('state').innerHTML='<option value="">Todos os estados</option>'+[...new Set(predictions.map(r=>r.uf))].sort().map(s=>`<option>${E(s)}</option>`).join('')}catch(e){$('sim-status').textContent=e.message;return}}simulate()}
function simulate(){if(!predictions)return;const target=Number($('target').value),g=$('sim-group').value,uf=$('state').value,q=$('search').value.toLowerCase().replace(/[.\/]/g,'');let all=predictions.filter(r=>(!uf||r.uf===uf)&&(!g||r[g])&&(!q||(r.processo+' '+r.substancias+' '+r.area).toLowerCase().replace(/[.\/]/g,'').includes(q)));all=all.map((r,order)=>({...r,order,score:r.prob[target]})).sort((a,b)=>b.score-a.score);const n=Math.ceil(all.length*Number($('capacity').value)/100),sel=all.slice(0,n),hits=sel.filter(r=>r.observed===target).length,ref=[...all].sort((a,b)=>(b.reference[target]-a.reference[target])||(a.order-b.order)).slice(0,n).filter(r=>r.observed===target).length;$('capacity-value').textContent=$('capacity').value+'%';$('sim-kpis').innerHTML=[['Áreas selecionadas',N(n)],['Alvos observados',N(hits)],['Precisão histórica',n?P(hits/n):'—'],['Referência por UF',n?P(ref/n):'—']].map(r=>`<div class="kpi"><span>${r[0]}</span><strong>${r[1]}</strong></div>`).join('');$('sim-status').textContent=`${N(all.length)} áreas no recorte da 8ª rodada. Ranking recalculado dentro deste recorte. Não é previsão para uma nova rodada.`;currentRows=sel.sort((a,b)=>sortDir*(sortKey==='score'?a.score-b.score:String(a[sortKey]).localeCompare(String(b[sortKey]),'pt-BR',{numeric:true})));const pages=Math.max(1,Math.ceil(sel.length/20));page=Math.min(page,pages-1);$('ranking-body').innerHTML=currentRows.slice(page*20,page*20+20).map(r=>`<tr><td>${E(F(r.processo))}</td><td>${E(r.uf)}</td><td>${E(r.substancias||'Não informada')}</td><td>${P(r.score)}</td><td>${model.labels[r.observed]}</td></tr>`).join('');$('page').textContent=`Página ${page+1} de ${pages}`;$('prev').disabled=page===0;$('next').disabled=page+1>=pages}
function renderJourney(){if(!summary)return;const g=$('journey-group').value,s=summary.journey.summary[g],rd=$('journey-round').value,d=rd?summary.journey.by_round[g][rd]:s;$('journey-stages').innerHTML=Object.entries(stages).map(([k,label])=>`<div class="stage"><span>${label}</span><strong>${N(d.marcos[k])}</strong></div>`).join('')+`<div class="stage"><span>Com CFEM positiva identificada</span><strong>${N(d.com_cfem_positiva)}</strong></div><div class="stage"><span>CFEM após associação</span><strong>${M(d.cfem_bruta)}</strong></div>`;$('journey-scope').textContent=`${N(d.arrematacoes_area_rodada)} arrematações · ${N(d.origens_com_vinculo)} processos de origem vinculados · ${N(d.processos_associados)} associados acompanhados. Até 31/12/2025.`;$('cfem-bars').innerHTML=bars(Object.entries(d.cfem_ano_bruta).map(([y,v])=>[y,v,M(v),'green']));if(journeys)showProcesses()}
async function loadJourney(){try{if(!journeys)journeys=await get('pesquisa/trajetorias_v5.json');$('process-controls').hidden=false;showProcesses();$('load-journey').hidden=true}catch(e){$('journey-scope').textContent=e.message}}
function showProcesses(){const g=$('journey-group').value,rd=$('journey-round').value,q=$('process-search').value.replace(/[.\/]/g,'').toLowerCase();const list=journeys.filter(r=>(!rd||String(r.rodada)===rd)&&(g==='todas'||(g==='estrategicos_2021'?r.minerais_estrategicos.length:r.alta_tecnologia))&&(!q||(r.processo_origem+' '+r.processo_associado+' '+r.substancias_cadastradas).replace(/[.\/]/g,'').toLowerCase().includes(q)));$('process-count').textContent=N(list.length)+' vínculos encontrados. Exibição dos primeiros 40; refine a busca.';$('process-list').innerHTML=list.slice(0,40).map(r=>`<tr><td><button class="button" data-process="${E(r.processo_associado)}">${E(F(r.processo_origem))}</button></td><td>${E(F(r.processo_associado))}</td><td>${r.rodada}ª</td><td>${E(r.substancias_cadastradas)}</td><td>${Object.keys(r.cfem_bruta_por_ano).length?M(Object.values(r.cfem_bruta_por_ano).reduce((a,v)=>a+v,0)):'Não localizado'}</td></tr>`).join('')}
function processDetail(id){const r=journeys.find(x=>x.processo_associado===id);if(!r)return;$('detail-title').textContent=F(r.processo_origem);$('detail-content').innerHTML=`<div class="network"><div class="node">${F(r.processo_origem)}<small>Processo da área arrematada</small></div><span aria-label="associado a">→</span><div class="node">${F(r.processo_associado)}<small>Processo associado · tipo 8</small></div></div><p>${E(r.substancias_cadastradas)} · ${r.rodada}ª rodada</p><ol class="timeline"><li><time>${r.data_associacao}</time>Associação registrada</li>${Object.entries(r.marcos_ate_2025).sort((a,b)=>a[1].localeCompare(b[1])).map(([k,dt])=>`<li><time>${dt}</time>${stages[k]}</li>`).join('')}</ol><h3>CFEM por ano de registro</h3>${table(['Ano','Valor'],Object.entries(r.cfem_bruta_por_ano).map(([y,v])=>[y,M(v)]))}<p class="caption">Sem registro não significa ausência de atividade. Associação ainda requer confirmação documental e espacial. Os eventos não certificam a fase vigente.</p>`;$('process-dialog').showModal()}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.view)));['group','round'].forEach(id=>$(id).addEventListener('change',renderOverview));['target','sim-group','state','search','capacity'].forEach(id=>$(id).addEventListener(id==='search'||id==='capacity'?'input':'change',()=>{page=0;simulate()}));document.querySelectorAll('[data-sort]').forEach(b=>b.addEventListener('click',()=>{if(sortKey===b.dataset.sort)sortDir*=-1;else{sortKey=b.dataset.sort;sortDir=1}simulate()}));$('prev').onclick=()=>{page--;simulate()};$('next').onclick=()=>{page++;simulate()};['journey-group','journey-round'].forEach(id=>$(id).onchange=renderJourney);$('load-journey').onclick=loadJourney;$('process-search').oninput=showProcesses;$('process-list').onclick=e=>{const b=e.target.closest('[data-process]');if(b)processDetail(b.dataset.process)};$('close-detail').onclick=()=>$('process-dialog').close();$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch(e){$('status').textContent='Tela cheia indisponível neste navegador.'}};
$('export').onclick=()=>{const csv='processo;uf;substancias;pontuacao;resultado\n'+currentRows.map(r=>[F(r.processo),r.uf,r.substancias,r.score,model.labels[r.observed]].map(s=>'"'+String(s).replaceAll('"','""')+'"').join(';')).join('\n');const u=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='mineria-selecao-retrospectiva.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};
async function init(){try{[model,summary]=await Promise.all([get('pesquisa/experimento_ml_v5.json'),get('pesquisa/resumo_v5.json')]);renderOverview();renderModels();$('status').textContent='Base congelada: 24/09/2026 · Experimento: '+new Date(model.created_at).toLocaleDateString('pt-BR')+' · CFEM até 2025';const route=location.hash.slice(1);navigate(['overview','models','simulation','journey','method'].includes(route)?route:'overview')}catch(e){$('status').textContent=e.message;$('status').classList.add('error')}}init();

document.querySelector('.brand').addEventListener('click',()=>navigate('overview'));
